targets.expr:
sum by (processor $grouping) (  
  label_replace(  
    label_replace(  
      ${metric:value}(  
        {  
          __name__=~".*otelcol_processor_.+accepted_spans.*",  
          processor=~"$processor",  
          job="$job",source="otelcol-telemetry"  
        }[$__rate_interval]  
      ),  
      "processor", "$1",  
      "__name__", "otelcol_processor_(?:(.+)_)?accepted_spans${suffix_total}"  
    ),  
    "__name__", "otelcol_processor_accepted_spans${suffix_total}",  
    "__name__", ".*"  
  )  
)

