    otelcol_exporter_queue_capacity{
        exporter=~"$exporter", job="$job",source="otelcol-telemetry"
    }
) by (exporter $grouping)

max(otelcol_process_uptime${suffix_seconds}${suffix_total}{service${divider:raw}instance${divider:raw}id=~".*",job="$job",source="otelcol-telemetry",service${divider:raw}version=".+"}) by (service${divider:raw}instance${divider:raw}id, service${divider:raw}name, service${divider:raw}version)
or
max(
  otelcol_process_uptime${suffix_seconds}${suffix_total}{service${divider:raw}instance${divider:raw}id=~".*",job="$job",source="otelcol-telemetry"} 
  * on(job, instance) 
  group_left(service${divider:raw}version) 
  topk by (job, instance) (1,
    target_info{job="$job",source="otelcol-telemetry"} 
    * on(job, instance) 
    group_left 
    label_replace(topk by (job, instance) (1, target_info{job="$job",source="otelcol-telemetry"}), "service${divider:raw}instance${divider:raw}id", "$1", "instance", "(.*)")
  )
) by (service${divider:raw}instance${divider:raw}id, service${divider:raw}name, service${divider:raw}version)
